package export_ohrats_rc_plugin_package_source

import (
	"crypto/sha256"
	"fmt"

	witTypes "go.bytecodealliance.org/pkg/wit/types"
	"wit_component/httpsource"
	"wit_component/ohrats_rc_plugin_http_client"
	"wit_component/ohrats_rc_plugin_package_source"
)

// maxComponentBytes bounds a downloaded component at 48 MiB.
const maxComponentBytes = 48 * 1024 * 1024

// Resolve fetches a component over HTTP(S) and pins the response body by its
// SHA-256 digest. The artifact name comes from the final, post-redirect URL.
func Resolve(scheme string, spec string) witTypes.Result[ohrats_rc_plugin_package_source.PackageArtifact, string] {
	if scheme != "http" && scheme != "https" {
		return witTypes.Err[ohrats_rc_plugin_package_source.PackageArtifact, string](
			fmt.Sprintf("HTTP source does not handle %q", scheme))
	}
	url, err := httpsource.NormalizeURL(scheme, spec)
	if err != nil {
		return witTypes.Err[ohrats_rc_plugin_package_source.PackageArtifact, string](err.Error())
	}
	response := ohrats_rc_plugin_http_client.Send(ohrats_rc_plugin_http_client.Request{
		Method: "GET",
		Url:    url,
		Headers: []ohrats_rc_plugin_http_client.Header{{
			Name:  "accept",
			Value: "application/wasm, application/octet-stream",
		}},
		Body:             []uint8{},
		MaxResponseBytes: maxComponentBytes,
	})
	if response.IsErr() {
		return witTypes.Err[ohrats_rc_plugin_package_source.PackageArtifact, string](response.Err())
	}
	value := response.Ok()
	if value.Status < 200 || value.Status >= 300 {
		return witTypes.Err[ohrats_rc_plugin_package_source.PackageArtifact, string](
			fmt.Sprintf("HTTP source returned status %d", value.Status))
	}
	name, err := httpsource.ArtifactName(value.FinalUrl)
	if err != nil {
		return witTypes.Err[ohrats_rc_plugin_package_source.PackageArtifact, string](err.Error())
	}
	return witTypes.Ok[ohrats_rc_plugin_package_source.PackageArtifact, string](
		ohrats_rc_plugin_package_source.PackageArtifact{
			Name:   name,
			Source: value.FinalUrl,
			Digest: fmt.Sprintf("sha256:%x", sha256.Sum256(value.Body)),
			Bytes:  value.Body,
		})
}
